    public async IAsyncEnumerable<JsonNode?> ListRunsAllAsync(Dictionary<string, string>? query = null, CancellationToken ct = default)
    {
        var p = query is not null ? new Dictionary<string, string>(query) : new Dictionary<string, string>();
        while (true)
        {
            var page = await ListRunsAsync(p, ct).ConfigureAwait(false);
            if (page?["data"] is JsonArray arr)
            {
                foreach (var item in arr) yield return item;
            }
            var next = page?["next_cursor"]?.GetValue<string>();
            if (string.IsNullOrEmpty(next)) yield break;
            p["cursor"] = next;
        }
    }

